WORKBEATS - THE WB HELPER TO PASTE INTO THE LOGGED-IN TAB (for the log-work process, see topic workbeats-log-work). Seeded 2026-09-28.

## Appendix B: helper to paste into the tab

Paste once per page load with the Claude in Chrome `javascript_tool` (or Playwright `page.evaluate`). Then call `WB.*` with `await`. Local times are UTC+7 `HH:MM`, days are `YYYY-MM-DD`.

```js
window.WB = (() => {
  const B = '/srv-workbeat/TimeTrackingService/';
  let token = null, me = null;

  // CSRF token: fetched with 'x-csrf-token: fetch'; it can rotate, so a 403 refetches it once.
  async function refresh() {
    const r = await fetch('/srv-workbeat/UserService/UserInfo', { headers: { 'x-csrf-token': 'fetch' } });
    token = r.headers.get('x-csrf-token') || sessionStorage.getItem('csrf-token');
    me = (await r.json()).value?.[0] || me;
  }
  async function get(path) {
    const r = await fetch(B + path);
    if (!r.ok) throw new Error(`${r.status} GET ${path}`);
    return (await r.json()).value;
  }
  async function post(action, body, retried) {
    if (!token) await refresh();
    const r = await fetch(B + action, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-csrf-token': token },
      body: JSON.stringify(body),
    });
    if (r.status === 403 && !retried) { await refresh(); return post(action, body, true); }
    const t = await r.text();
    if (!r.ok) throw new Error(`${r.status} ${action}: ${t.slice(0, 300)}`);
    return JSON.parse(t);
  }

  const utc = (day, hhmm) => new Date(`${day}T${hhmm}:00+07:00`).toISOString();
  const local = iso => new Date(new Date(iso).getTime() + 7 * 3600e3).toISOString().slice(0, 16).replace('T', ' ');
  const plus = (iso, minutes) => new Date(new Date(iso).getTime() + minutes * 60e3).toISOString();
  const q = s => encodeURIComponent(s);

  async function userId() { if (!me) await refresh(); return me.userID || me.email; }

  // Workbeats project by visible name, e.g. 'INTERNAL-SMDG-360 View'.
  async function project(name) {
    const v = await get(`Projects?$select=ID,shortName,fullName&$filter=${q(`fullName eq '${name}' or shortName eq '${name}'`)}`);
    if (v.length !== 1) throw new Error(`project '${name}': ${v.length} matches`);
    return v[0];
  }

  // Tasks of a project; pass a name to look for an exact match (null when absent).
  async function findTask(projectId, name) {
    const v = await get(`Tasks?$select=ID,name,billable,timeEstimate,isDone&$filter=${q(`projectId eq ${projectId}`)}&$top=500`);
    return name ? v.find(t => t.name === name) || null : v;
  }

  // Every entry of the week starting `monday`, sorted by start, local time.
  async function readWeek(monday) {
    const from = utc(monday, '00:00'), to = plus(from, 7 * 24 * 60 - 1);
    const uid = await userId();
    const logs = await get(`TimeLogs?$select=ID,startTime,endTime,entryDate,duration,taskId,projectId,description,billable,status&$filter=${q(`userId eq '${uid}' and entryDate ge '${from}' and entryDate le '${to}'`)}&$top=500`);
    const ids = [...new Set(logs.map(l => l.taskId))];
    const tasks = ids.length ? await get(`Tasks?$select=ID,name,timeEstimate&$expand=project($select=shortName)&$filter=${q(ids.map(i => `ID eq ${i}`).join(' or '))}&$top=500`) : [];
    const tm = Object.fromEntries(tasks.map(t => [t.ID, t]));
    return logs
      .map(l => ({ id: l.ID, start: local(l.startTime), end: local(l.endTime).slice(11), hours: l.duration / 60, status: l.status,
                   project: tm[l.taskId]?.project?.shortName, task: tm[l.taskId]?.name, taskId: l.taskId, projectId: l.projectId,
                   billable: l.billable, description: l.description }))
      .sort((a, b) => a.start.localeCompare(b.start));
  }

  // New task + its first log. Returns { taskId, timeLogId }.
  async function logTask(projectId, taskName, day, start, hours, description, billable = false) {
    const s = utc(day, start), minutes = Math.round(hours * 60);
    return post('logTask', { input: { projectId, taskName, description, billable,
      entryDate: s, startTime: s, endTime: plus(s, minutes), duration: minutes, status: 'draft' } });
  }

  // Create (no id) or edit (with id) logs on existing tasks.
  // entries: [{ id?, taskId, projectId, day, start, hours, description, billable }]
  async function saveLogs(entries) {
    const uid = await userId();
    return post('bulkTimeLogs', { createBulkTimeLogsDatas: entries.map(e => {
      const s = utc(e.day, e.start);
      return { ...(e.id ? { ID: e.id } : {}), startTime: s, endTime: plus(s, Math.round(e.hours * 60)), entryDate: s,
               description: e.description, billable: e.billable ?? false, taskId: e.taskId, projectId: e.projectId,
               userId: uid, status: 'draft' };
    }) });
  }

  // Submit exactly these log ids. Only after the user approved.
  async function submit(timeLogIds) {
    return post('submitTimeLogs', { input: { timeLogIds, userId: await userId() } });
  }

  // Delete draft logs. Only when the user asked.
  async function deleteLogs(timeLogIds) { return post('deleteTimeLogs', { timeLogIds }); }

  return { project, findTask, readWeek, logTask, saveLogs, submit, deleteLogs };
})();
'WB ready';
```

Typical run:

```js
const p = await WB.project('INTERNAL-SMDG-360 View');
await WB.readWeek('2026-09-21');                        // step 5: what is already there
const name = '[FEATURE] M360 - Centralized View clickable tiles, last update column and pager';
const existing = await WB.findTask(p.ID, name);          // step 8: never duplicate
const r = existing
  ? await WB.saveLogs([{ taskId: existing.ID, projectId: p.ID, day: '2026-09-25', start: '08:30', hours: 2,
                          description: 'Made summary tiles clickable filters and added a Last update column.' }])
  : await WB.logTask(p.ID, name, '2026-09-25', '08:30', 2,
                     'Made summary tiles clickable filters and added a Last update column.');
await WB.readWeek('2026-09-21');                        // step 9: verify
await WB.submit([r.timeLogId /* ...every approved log id */]);   // step 10, after approval
```

`saveLogs` does not return the new log IDs; read them back with `readWeek()` before submitting.

